insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('ccc61179-fc80-5554-892f-a92044e0317a', 'rg5-story-details-inference-p02', (select id from public.skills where slug = 'read-g5-story-details-inference'), null,
        '3-5', $q$Backstage$q$, $q$My fingers play a piano song
on the edge of my folding chair,
though there is no piano here,
just my knees and the dusty air.

Ten names before mine on the list.
Then nine. Then six. Then two.
My mouth is dry as a paper sack.
My hands forget what they knew.

Then Grandpa Tomas, in the second row,
lifts up his hat an inch,
the signal from our Sunday lessons
that means, "You've got this. It's a cinch."

I walk out to the shining bench.
The lights are warm and bright.
I play the first slow notes for him,
and the rest come out just right.$q$, 'draft')
