-- Passage rg5-story-details-inference-p05
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('9d1ccdda-e7ae-5280-ad40-823d28678bec', 'rg5-story-details-inference-p05', (select id from public.skills where slug = 'read-g5-story-details-inference'), null,
        '3-5', $q$Ghost Fox$q$, $q$Kenji Watanabe had worked on his maze game for a month. The library was holding a showcase for young coders on Saturday. His game was going to be on a big screen near the front desk.

On Friday night, he asked his little sister, Ruthie, to test it. She pressed the arrow keys, and the tiny orange fox began to move. Then it walked straight through a wall.

Kenji groaned. "That's a bug," he said. "It's not supposed to do that."

Ruthie giggled and steered the fox through another wall, and another. "It's a ghost fox!" she said. "This is the best part."

Kenji opened his laptop and studied his code for a long time. He found the mistake on line forty-two. He fixed it, and the fox bumped into walls the way it should.

Then he kept typing. Ruthie leaned over his shoulder to watch.

At the showcase the next day, a sign beside the screen said, "Press G for Ghost Mode." A line of younger kids waited for a turn. Ruthie stood at the front of the line, explaining the rules to everyone behind her.$q$, 'draft')
