-- Passage rg5-story-details-inference-p07
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('3263ec3c-dacb-579a-98d8-687d2026ecd9', 'rg5-story-details-inference-p07', (select id from public.skills where slug = 'read-g5-story-details-inference'), null,
        '3-5', $q$Before Anyone Wakes$q$, $q$Before anyone wakes on Juniper Street,
the snow lies smooth and deep.
I pull on my boots and my brother's old gloves
while the houses are still asleep.

I clear our walk, then the one next door,
where Mrs. Abara lives alone.
Her cane leans by the window glass.
Her steps are slick as stone.

I work until my cheeks are pink
and the sidewalk shines bare and gray.
Then I tiptoe home and hang my gloves
and never say a word all day.

At noon, a plate of warm sweet bread
sits waiting on our stair.
A note beneath it, shaky and small,
says, "Thank you for being there."$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
