  ('f19f6274-e687-5ef8-a054-0bd29235e367', null, (select id from public.skills where slug = 'read-g5-story-details-inference'), null, 'easy',
   $q$When does the speaker shovel the snow?$q$, $q$[{"text":"Early, before anyone wakes","is_correct":true},{"text":"After school, with a brother","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"At noon, after lunch is over","is_correct":false,"misconception_token":"wrong-event"},{"text":"Late at night, after dark","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$Early, before anyone wakes$q$, $q$The first line says "Before anyone wakes on Juniper Street," and the houses "are still asleep." Noon is when the bread appears, not when the shoveling happens.$q$, 'draft', '3263ec3c-dacb-579a-98d8-687d2026ecd9')
