-- Passage rg5-story-details-inference-p08
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('7ff0085c-5c25-586e-8494-52f300151b0f', 'rg5-story-details-inference-p08', (select id from public.skills where slug = 'read-g5-story-details-inference'), null,
        '3-5', $q$The Napkin Map$q$, $q$On Sofia Petrov's first day at Linden Elementary, she got lost three times. She walked into the art room instead of the library. She found the gym when she was looking for the nurse. By lunch, she was sitting alone at the end of a long table, staring at her sandwich.

A boy named Tariq Mansour sat down across from her. "You look like you've been walking in circles," he said. He pulled a paper napkin from the holder and took a pencil out of his pocket. In five minutes, he had drawn the whole school. He added the hallways, the stairs, and a star on the water fountain that was the coldest.

Sofia kept the napkin in her pocket all week. By Friday, the pencil lines were smudged and the corners were soft. But she did not need it anymore.

The next Monday, the principal brought a new girl into Sofia's classroom. The girl clutched her backpack straps with both hands. Her eyes darted from the door to the windows and back again.

At lunch, Sofia looked for her. Then she reached into her pocket, smoothed out the napkin on the table, and slid it across.$q$, 'draft')
